using MediatR;using Microsoft.EntityFrameworkCore;using MSA.NotificationService.Domain;using MSA.Repositories.Persistence;
namespace MSA.NotificationService.Infrastructure;
public sealed class NotificationDbContext(DbContextOptions<NotificationDbContext> o,IMediator m):MessagingDbContext(o,m){public DbSet<Notification> Notifications=>Set<Notification>();public DbSet<NotificationTemplate> Templates=>Set<NotificationTemplate>();public DbSet<UserNotificationPreference> Preferences=>Set<UserNotificationPreference>();protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<Notification>(e=>{e.ToTable("notifications");e.HasKey(x=>x.Id);e.HasIndex(x=>x.DeduplicationKey).IsUnique();e.HasIndex(x=>new{x.Status,x.NextAttemptOnUtc,x.LockedUntilUtc});e.Property(x=>x.LastError).HasMaxLength(2000);e.Property(x=>x.Version).IsConcurrencyToken();});b.Entity<NotificationTemplate>(e=>{e.ToTable("notification_templates");e.HasKey(x=>x.Id);e.HasIndex(x=>x.Code).IsUnique();});b.Entity<UserNotificationPreference>(e=>{e.ToTable("user_notification_preferences");e.HasKey(x=>x.Id);e.HasIndex(x=>x.UserId).IsUnique();});}}
